package main

import (
	"bufio"
	"fmt"
	"os"
	"sort"
)

const LIMIT = 1000000000

func main() {
	in := bufio.NewReader(os.Stdin)
	var n, k int64
	if _, err := fmt.Fscan(in, &n, &k); err != nil {
		return
	}

	// Generate all lucky numbers up to LIMIT
	lucky := []int64{}
	var dfs func(int64)
	dfs = func(x int64) {
		if x > LIMIT {
			return
		}
		if x > 0 {
			lucky = append(lucky, x)
		}
		dfs(x*10 + 4)
		dfs(x*10 + 7)
	}
	dfs(0)
	sort.Slice(lucky, func(i, j int) bool { return lucky[i] < lucky[j] })

	// Count lucky numbers <= n
	luckyCountN := 0
	for _, v := range lucky {
		if v <= n {
			luckyCountN++
		} else {
			break
		}
	}

	// Find m such that m! >= k
	m := 0
	fact := int64(1)
	for i := 1; i <= 20; i++ { // 20! > 1e18 > LIMIT
		if fact >= k {
			break
		}
		fact *= int64(i)
		m = i
	}
	// m is the number of elements at the end that are permuted.
	// Actually, if fact >= k at step i, then m = i.
	// But we need the smallest m such that m! >= k.
	// The loop above sets m to the last i where fact < k was true? Let's trace.
	// fact=1, k=4. i=1: fact=1 < 4 -> m=1. i=2: fact=2 < 4 -> m=2. i=3: fact=6 >= 4 -> break. m=2.
	// Correct m should be 3 because 3! >= 4.
	// Fix: m is the current i when loop breaks.
	// Let's re-do logic.
	m = 0
	fact = 1
	for i := 1; i <= 20; i++ {
		if fact >= k {
			m = i - 1
			break
		}
		fact *= int64(i)
		if fact >= k {
			m = i
			break
		}
	}
	// If k=1, fact=1 >=1 at i=1 start. m=0. Correct.
	// If k=4, i=1: fact=1<4, fact=1. i=2: fact=1<4, fact=2. i=3: fact=2<4, fact=6>=4 -> m=3. Correct.

	if m > int(n) {
		fmt.Println("-1")
		return
	}

	// The first n-m elements are fixed: 1, 2, ..., n-m
	// Count lucky numbers in [1, n-m]
	fixedEnd := n - int64(m)
	count := 0
	for _, v := range lucky {
		if v <= fixedEnd {
			count++
		} else {
			break
		}
	}

	// Generate k-th permutation of the last m numbers
	// Numbers are: fixedEnd + 1, fixedEnd + 2, ..., n
	nums := make([]int64, m)
	for i := 0; i < m; i++ {
		nums[i] = fixedEnd + 1 + int64(i)
	}

	// k is 1-based. Convert to 0-based index.
	k--

	// Precompute factorials up to m
	facts := make([]int64, m+1)
	facts[0] = 1
	for i := 1; i <= m; i++ {
		facts[i] = facts[i-1] * int64(i)
	}

	perm := make([]int64, m)
	available := make([]int64, m)
	copy(available, nums)

	for i := m; i >= 1; i-- {
		f := facts[i-1]
		idx := k / f
		k %= f
		perm[m-i] = available[idx]
		available = append(available[:idx], available[idx+1:]...)
	}

	// Check positions in the permuted part
	// Global positions are fixedEnd + 1 ... n
	// Local indices 0 ... m-1 correspond to global positions fixedEnd + 1 + i
	for i := 0; i < m; i++ {
		pos := fixedEnd + 1 + int64(i)
		val := perm[i]
		// Check if pos and val are lucky
		// Since pos, val <= n <= 1e9, we can binary search in lucky slice
		isLuckyPos := false
		isLuckyVal := false
		// Binary search for pos
		idx := sort.Search(len(lucky), func(j int) bool { return lucky[j] >= pos })
		if idx < len(lucky) && lucky[idx] == pos {
			isLuckyPos = true
		}
		// Binary search for val
		idx = sort.Search(len(lucky), func(j int) bool { return lucky[j] >= val })
		if idx < len(lucky) && lucky[idx] == val {
			isLuckyVal = true
		}
		if isLuckyPos && isLuckyVal {
			count++
		}
	}

	fmt.Println(count)
}
